new_function_ddl.apply_retention_policy(p_table_name text:
CREATE OR REPLACE FUNCTION quant.apply_retention_policy(p_table_name text, p_batch_size integer DEFAULT NULL::integer)
 RETURNS TABLE(deleted_rows bigint, cutoff timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
DECLARE
    policy quant.retention_policies%ROWTYPE;
    batch integer;
    removed bigint := 0;
BEGIN
    SELECT * INTO policy FROM quant.retention_policies p WHERE p.table_name = p_table_name;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'no retention policy for quant.%', p_table_name;
    END IF;
    IF NOT policy.enabled THEN
        RAISE EXCEPTION 'retention policy for quant.% is disabled', p_table_name;
    END IF;
    batch := coalesce(p_batch_size, policy.batch_size);
    IF batch <= 0 THEN
        RAISE EXCEPTION 'batch size must be positive';
    END IF;
    cutoff := now() - make_interval(days => policy.retention_days);
    EXECUTE format(
        'DELETE FROM quant.%I t WHERE t.ctid = ANY(ARRAY(SELECT s.ctid FROM quant.%I s WHERE s.%I < $1 LIMIT $2))',
        policy.table_name, policy.table_name, policy.time_column)
    USING cutoff, batch;
    GET DIAGNOSTICS removed = ROW_COUNT;
    UPDATE quant.retention_policies p
       SET last_run_at = now(),
           last_deleted_rows = coalesce(p.last_deleted_rows, 0) + removed,
           updated_at = now()
     WHERE p.table_name = p_table_name;
    deleted_rows := removed;
    RETURN NEXT;
END
$function$

new_function_ddl.capture_factor_maintenance_change():
CREATE OR REPLACE FUNCTION quant.capture_factor_maintenance_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    DECLARE rid text; old_image jsonb; new_image jsonb; key_image jsonb;
    BEGIN
      rid := current_setting('quant.factor_run_id',true);
      IF rid IS NULL OR rid = '' THEN RETURN NULL; END IF;
      IF TG_OP <> 'INSERT' THEN old_image := to_jsonb(OLD); END IF;
      IF TG_OP <> 'DELETE' THEN new_image := to_jsonb(NEW); END IF;
      key_image := jsonb_build_object('symbol',coalesce(new_image,old_image)->'symbol',
                                     'trading_date',coalesce(new_image,old_image)->'trading_date');
      IF TG_TABLE_NAME = 'daily_adjustment_factors' THEN
        key_image := key_image || jsonb_build_object('provider',coalesce(new_image,old_image)->'provider');
      ELSE
        IF old_image IS NOT NULL THEN old_image := jsonb_build_object('adj_factor',old_image->'adj_factor'); END IF;
        IF new_image IS NOT NULL THEN new_image := jsonb_build_object('adj_factor',new_image->'adj_factor'); END IF;
      END IF;
      IF old_image IS NOT DISTINCT FROM new_image THEN RETURN NULL; END IF;
      INSERT INTO quant.factor_maintenance_changes(run_id,table_name,row_key,before_image,after_image)
      VALUES(rid::uuid,TG_TABLE_NAME,key_image,old_image,new_image);
      RETURN NULL;
    END $function$
